export function extoRev21Norm(value){return String(value==null?'':value).replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim().toUpperCase();}
const EXTO_REV21_FIELD_TO_DROPDOWN=Object.fromEntries(EXTO_REV21_COLUMNS.filter(column=>column.dropdown).map(column=>[column.field,column.dropdown]));
const EXTO_REV21_CANONICAL=Object.fromEntries(Object.entries(EXTO_REV21_VOCABULARY).map(([name,values])=>[name,new Map(values.map(value=>[extoRev21Norm(value),String(value)]))]));
const EXTO_REV21_UPN_SET=new Set((EXTO_REV21_VOCABULARY.UPN||[]).map(extoRev21Norm));
const EXTO_REV21_SYSTEMS_BY_UPN=new Map();
for(const name of EXTO_REV21_VOCABULARY['System Name']||[]){const match=extoRev21Norm(name).match(/^([^ ]+)/);if(!match)continue;const list=EXTO_REV21_SYSTEMS_BY_UPN.get(match[1])||[];list.push(name);EXTO_REV21_SYSTEMS_BY_UPN.set(match[1],list);}
/* Letter-code UPNs have no System Name that begins with the code, so their
   pairings are linked explicitly. Confirmed so far: UPN RR belongs to the CSA
   system, written either as the bare code or in full — "Civil Structural
   Architectural Systems (CSA)" — and SEC to Security ("Security Systems" is
   the VF Exto Upload Template spelling). MISC is deliberately NOT linked: it is a catch-all,
   and the engine flags every MISC row for a second look instead. */
const EXTO_REV21_UPN_SYSTEM_LINKS=[['RR','Civil Structural Architectural Systems (CSA)'],['RR','CSA'],['SEC','Security Systems'],['SEC','Security']];
for(const [code,name] of EXTO_REV21_UPN_SYSTEM_LINKS){const key=extoRev21Norm(code),list=EXTO_REV21_SYSTEMS_BY_UPN.get(key)||[];if(!list.includes(name))list.push(name);EXTO_REV21_SYSTEMS_BY_UPN.set(key,list);}
/* Small read-only lookups the audit engine needs: is this a VF Exto Upload Template UPN, and
   which approved System Names belong to it. Letter-code UPNs (RR / SEC / MISC)
   have no System Name beginning with the code, so callers must use the by-UPN
   list rather than a "starts with the UPN" test. */
export function extoRev21IsUpn(value){return EXTO_REV21_UPN_SET.has(extoRev21Norm(value));}
export function extoRev21SystemsForUpn(upn){return [...(EXTO_REV21_SYSTEMS_BY_UPN.get(extoRev21Norm(upn))||[])];}
export function extoRev21IsSystemName(value){return EXTO_REV21_CANONICAL['System Name'].has(extoRev21Norm(value));}
export function extoRev21Canonical(field,value){
  const normalized=extoRev21Norm(value);if(!normalized)return '';
  const dropdown=EXTO_REV21_FIELD_TO_DROPDOWN[field],values=dropdown&&EXTO_REV21_CANONICAL[dropdown];
  return values&&values.get(normalized)||'';
}
export function extoRev21ValidatePartial(record){
  const issues=[];
  for(const [field,dropdown] of Object.entries(EXTO_REV21_FIELD_TO_DROPDOWN)){
    const value=String(record&&record[field]==null?'':record[field]).trim();if(!value)continue;
    if(!EXTO_REV21_CANONICAL[dropdown].has(extoRev21Norm(value)))issues.push({field,value,dropdown,reason:'Value is not in the approved VF Exto Upload Template dropdown'});
  }
  return issues;
}
/* ---- linking an L2 milestone name to its UPN ----
   In priority order:
   1. an explicit "UPN 237" marker (also lists: "UPN 118, 119");
   2. a UPN written in parentheses;
   3. a standalone three-digit UPN token — never digits inside a longer run,
      so the milestone sequence in "SP-L2-M1-1186" can no longer read as 118;
   4. the system's name or abbreviation: an abbreviation the Upload Template
      itself carries in parentheses (GAH, CSA), an acronym of the name's words
      (Continuous Power Supply -> CPS), or the full name spelled out.
   Returns {upns:[...], via} — empty upns when nothing links. */
const EXTO_REV21_MILESTONE_NAME_KEYS=(()=>{
  const keys=new Map();
  const addKey=(key,upn)=>{if(key.length<3)return;const set=keys.get(key)||new Set();set.add(upn);keys.set(key,set);};
  const STOP=new Set(['SYSTEM','SYSTEMS','AND','THE','FOR','OF','R/S','S/R']);
  for(const name of EXTO_REV21_VOCABULARY['System Name']||[]){
    const normalized=extoRev21Norm(name),upnMatch=normalized.match(/^([0-9]{3}|[A-Z]{2,4}) /);
    const upn=upnMatch?upnMatch[1]:'';if(!upn||!EXTO_REV21_UPN_SET.has(upn))continue;
    for(const inner of normalized.matchAll(/\(([^)]+)\)/g))addKey(inner[1].trim(),upn);
    const body=normalized.replace(/^([0-9]{3}|[A-Z]{2,4}) +/,'').replace(/\([^)]*\)/g,' ').trim();
    const words=body.split(/[^A-Z0-9]+/).filter(word=>word&&!STOP.has(word)&&/^[A-Z]/.test(word));
    if(words.length>=2)addKey(words.map(word=>word[0]).join(''),upn);
    if(body.length>=8)addKey(body,upn);
  }
  return keys;
})();
export function extoRev21MilestoneUpns(name){
  const text=extoRev21Norm(name);if(!text)return {upns:[],via:''};
  const valid=value=>EXTO_REV21_UPN_SET.has(value);
  const marker=text.match(/\bUPN[\s:#-]*((?:[0-9]{3})(?:\s*[,&/+]\s*[0-9]{3})*)/);
  if(marker){const upns=[...new Set(marker[1].split(/[^0-9]+/).filter(Boolean).filter(valid))];if(upns.length)return {upns,via:'the UPN marker in the name'};}
  const parens=[];for(const inner of text.matchAll(/\(([^)]+)\)/g))for(const token of inner[1].split(/[^A-Z0-9]+/))if(/^[0-9]{3}$/.test(token)&&valid(token))parens.push(token);
  if(parens.length)return {upns:[...new Set(parens)],via:'the UPN in parentheses'};
  const stripped=text.replace(/\([^)]*\)/g,' ');
  const standalone=[...new Set([...stripped.matchAll(/(?:^|[^0-9])([0-9]{3})(?![0-9])/g)].map(match=>match[1]).filter(valid))];
  if(standalone.length)return {upns:standalone,via:'the UPN in the name'};
  const hits=new Set();
  const tokens=new Set(stripped.split(/[^A-Z0-9/]+/).filter(Boolean));
  for(const [key,upns] of EXTO_REV21_MILESTONE_NAME_KEYS){
    const matched=key.includes(' ')?stripped.includes(key):tokens.has(key);
    if(matched)for(const upn of upns)hits.add(upn);
  }
  if(hits.size)return {upns:[...hits],via:'the system name it spells out'};
  return {upns:[],via:''};
}

export function extoRev21UpnCandidates(tag){
  const text=String(tag==null?'':tag),found=new Set();let match;
  /* UPN is the first three-digit run after a nomenclature boundary. Some sites
     append a panel sequence immediately after it (RIO6500); the leading 650 is
     still the UPN, while later overlapping digits must not become candidates. */
  const pattern=/(^|[^0-9])([0-9]{3})/g;
  while((match=pattern.exec(text))){const value=extoRev21Norm(match[2]);if(EXTO_REV21_UPN_SET.has(value))found.add(value);if(!match[0].length)pattern.lastIndex++;}
  return [...found];
}
export function extoRev21SystemName(upn,description,allowUniqueUpn=false){
  const key=extoRev21Norm(upn);if(!key)return {value:'',status:'missing-upn',candidates:[]};
  const composed=extoRev21Norm(key+' '+String(description==null?'':description));
  const exact=EXTO_REV21_CANONICAL['System Name'].get(composed);if(exact)return {value:exact,status:'exact',candidates:[exact]};
  const candidates=EXTO_REV21_SYSTEMS_BY_UPN.get(key)||[];
  if(allowUniqueUpn&&candidates.length===1)return {value:candidates[0],status:'unique-upn',candidates};
  return {value:'',status:candidates.length?'description-mismatch':'unknown-system',candidates:[...candidates]};
}
export function extoRev21EffectiveDiscipline(value){
  const raw=String(value==null?'':value).trim();
  return /^(I\s*(?:&|AND)\s*C|INSTRUMENTATION(?:\s*(?:&|AND)\s*CONTROLS?)?)$/i.test(raw)?'FACILITIES MONITORING SYSTEM':(extoRev21Canonical('discipline',raw)||raw);
}
export function extoRev21EffectiveMel(row){
  const tag=String(row&&row.tag==null?'':row.tag).trim(),rawUpn=String(row&&row.upn==null?'':row.upn).trim();
  const rawDiscipline=String(row&&row.discipline==null?'':row.discipline).trim(),description=String(row&&row.systemDescription==null?'':row.systemDescription).trim();
  const isInstrumentation=extoRev21EffectiveDiscipline(rawDiscipline)==='FACILITIES MONITORING SYSTEM'&&extoRev21Norm(rawDiscipline)!=='FACILITIES MONITORING SYSTEM';
  const upnCandidates=isInstrumentation?extoRev21UpnCandidates(tag):[];
  const effectiveUpn=isInstrumentation?(upnCandidates.length===1?upnCandidates[0]:''):rawUpn;
  const effectiveDiscipline=extoRev21EffectiveDiscipline(rawDiscipline);
  const system=extoRev21SystemName(effectiveUpn,description,isInstrumentation);
  const composed=effectiveUpn&&description?(effectiveUpn+' '+description).replace(/\s+/g,' ').trim():description;
  const issues=[];
  if(isInstrumentation&&upnCandidates.length!==1)issues.push({ruleId:upnCandidates.length?'mel.ic-upn-ambiguous':'mel.ic-upn-missing',field:'UPN',reason:upnCandidates.length?'Multiple approved UPN values occur in the I&C Equipment Tag':'No approved UPN value occurs in the I&C Equipment Tag',candidates:upnCandidates});
  if(effectiveUpn&&!system.value)issues.push({ruleId:'mel.system-name-unresolved',field:'System Name',reason:system.status==='description-mismatch'?'The MEL System Description does not resolve to an approved Exto System Name for this UPN':'The UPN and MEL System Description do not resolve to an approved Exto System Name',candidates:system.candidates});
  return {rawUpn,rawDiscipline,effectiveUpn,effectiveDiscipline,effectiveSystemName:(system.value||composed).replace(/\s+/g,' ').trim(),isInstrumentation,systemResolution:system.status,issues};
}
